proc read_libraries {} {
  global tech_lef std_cell_lef extra_lef
  global liberty_file liberty_files extra_liberty

  read_lef $tech_lef
  read_lef $std_cell_lef
  foreach file $extra_lef { read_lef $file }
  set corners [sta::corners]
  if { [llength $corners] > 1 } {
    foreach corner $corners {
      set corner_name [$corner name]
      set corner_index [lsearch $liberty_files $corner_name]
      if { $corner_index == -1 } {
        error "No liberty file in \$liberty_files for corner $corner_name."
      } else {
        set liberty_file [lindex $liberty_files [expr $corner_index + 1]]
        read_liberty -corner $corner_name $liberty_file
      }
    }
  } else {
    read_liberty $liberty_file
  }
  foreach file $extra_liberty { read_liberty $file }
}

proc have_macros {} {
  set db [::ord::get_db]
  set block [[$db getChip] getBlock]
  foreach inst [$block getInsts] {
    set inst_master [$inst getMaster]
    # BLOCK means MACRO cells
    if { [string match [$inst_master getType] "BLOCK"] } {
      return 1
    }
  }
  return 0
}

proc derate_layer_wire_rc { layer_name corner derate_factor } {
  set layer [[ord::get_db_tech] findLayer $layer_name]
  lassign [rsz::dblayer_wire_rc $layer] r c
  # ohm/meter -> kohm/micron
  set r_ui [expr $r * 1e-3 * 1e-6]
  # F/meter -> fF/micron
  set c_ui [expr $c * 1e+15 * 1e-6]
  set_layer_rc -layer $layer_name -corner $corner \
    -resistance [expr $r_ui * $derate_factor] \
    -capacitance [expr $c_ui * $derate_factor]
}

proc define_metric { name header1 header2 field_width fmt cmp_op limit_expr } {
  variable metrics
  dict set metrics $name [list $header1 $header2 $field_width $fmt $cmp_op $limit_expr]
}

proc metric_names {} {
  variable metrics
  return [dict keys $metrics]
}

proc metric_header1 { name } {
  variable metrics
  lassign [dict get $metrics $name] header1 header2 field_width fmt cmp_op limit_expr
  return $header1
}

proc metric_header2 { name } {
  variable metrics
  lassign [dict get $metrics $name] header1 header2 field_width fmt cmp_op limit_expr
  return $header2
}

proc metric_tool_name { name } {
  regexp "(...)::.*" $name ignore tool
  return $tool
}

proc metric_field_width { name } {
  variable metrics
  lassign [dict get $metrics $name] header1 header2 field_width fmt cmp_op limit_expr
  return $field_width
}

proc metric_format { name } {
  variable metrics
  lassign [dict get $metrics $name] header1 header2 field_width fmt cmp_op limit_expr
  return $fmt
}

proc metric_json_key { name } {
  return $name
}

proc metric_cmp_op { name } {
  variable metrics
  lassign [dict get $metrics $name] header1 header2 field_width fmt cmp_op limit_expr
  return $cmp_op
}

proc metric_limit_expr { name } {
  variable metrics
  lassign [dict get $metrics $name] header1 header2 field_width fmt cmp_op limit_expr
  return $limit_expr
}

proc cmp_op_negated { cmp_op } {
  if { $cmp_op == "<" } {
    return ">="
  } elseif { $cmp_op == "<=" } {
    return ">"
  } elseif { $cmp_op == ">" } {
    return "<="
  } elseif { $cmp_op == ">=" } {
    return "<"
  } elseif { $cmp_op == "==" } {
    return "!="
  } else {
    error "unknown comparison operator"
  }
}

